import statistics
def solve(label, data):
    s = sorted(data)
    n = len(s)
    print(label + ": " + ", ".join(str(x) for x in data))
    print("  sorted: " + ", ".join(str(x) for x in s))
    if n % 2 == 1:
        print(f"  n = {n} is odd: position {(n + 1) // 2} holds the median, {s[n // 2]}")
    else:
        a = s[n // 2 - 1]
        b = s[n // 2]
        print(f"  n = {n} is even: positions {n // 2} and {n // 2 + 1} give ({a} + {b})/2 = {(a + b) / 2}")
    counts = {}
    for x in s:
        if x in counts:
            counts[x] = counts[x] + 1
        else:
            counts[x] = 1
    print("  counts: " + ", ".join(f"{x}: {counts[x]}" for x in counts))
    top = max(counts.values())
    modes = [x for x in counts if counts[x] == top]
    if top == 1:
        print("  no mode: each value appears once")
    elif len(modes) == 1:
        print(f"  mode: {modes[0]}, {top} times")
    else:
        print("  modes: " + ", ".join(str(x) for x in modes) + f", {top} times each")
    print(f"  statistics: median {statistics.median(data)}, multimode {statistics.multimode(s)}")
solve("Case 1 · an odd count", [7, 2, 9, 4, 5])
solve("Case 2 · an even count", [8, 3, 6, 1])
solve("Case 3 · shoe sizes", [7, 8, 8, 9, 8, 10, 7])
solve("Case 4 · two modes", [1, 3, 1, 2, 3])

